param(
    [string]$ProjectRoot = "D:\Projects\Hisse-Robotu"
)

$ErrorActionPreference = "Stop"
Set-StrictMode -Version Latest

$Phase5 = Join-Path $ProjectRoot "Hisse-Robotu-Next-Day-Phase5-T1-Outcome-Accountability-V1.ps1"
$Discovery = Join-Path $ProjectRoot "_discovery"

if (-not (Test-Path -LiteralPath $Phase5 -PathType Leaf)) {
    throw "PHASE5_SCRIPT_MISSING=$Phase5"
}

New-Item -ItemType Directory -Force -Path $Discovery | Out-Null
$stamp = Get-Date -Format "yyyyMMdd-HHmmss"
$Phase6 = Join-Path $Discovery ("Hisse-Robotu-Next-Day-Phase6-20-Session-Walk-Forward-Readiness-V1-" + $stamp + ".ps1")
[IO.File]::WriteAllBytes($Phase6, [Convert]::FromBase64String(""))

Write-Host "=== HISSE ROBOTU — NEXT-DAY CONTINUE PHASE 5 -> PHASE 6 V1 ==="
Write-Host "AUTO_ADVANCE_ON_SUCCESS=YES"
Write-Host "PHASE5=START"

try {
    & $Phase5 -ProjectRoot $ProjectRoot
    Write-Host "PHASE5_CHAIN=PASS"
    Write-Host "PHASE6=AUTO_START"
    & $Phase6 -ProjectRoot $ProjectRoot
    Write-Host "PHASE5_PHASE6_CHAIN=SUCCESS"
}
catch {
    Write-Host "CONTINUE_CHAIN=FAILED"
    Write-Host "ERROR=$($_.Exception.Message)"
    throw
}
